(function(root){
'use strict';
function body(W){return `<div class="studio-hero"><div><div class="eyebrow"><span class="live-dot"></span>TECH HORIZON / STUDIO</div><h1>Hiểu rồi.<br><span>Thử ngay thôi.</span></h1><p>Một góc thực hành nhỏ cho những việc bạn gặp mỗi ngày. Chọn công cụ, nhập thông tin và mang kết quả đi dùng.</p><span class="studio-local">6 công cụ · Xử lý ngay trên trình duyệt</span></div><div class="studio-hero-art" aria-hidden="true"><div class="studio-orbit"></div><div class="studio-window"><span>TECH HORIZON / WORKSPACE</span><i></i><i></i><i></i><strong>idea <b>→</b> action</strong><small>KHÁM PHÁ · THỰC HÀNH · LÀM CHỦ</small></div><span class="studio-symbol">✳</span></div></div>
<nav class="studio-tabs" role="tablist" aria-label="Chọn công cụ">${W.catalog.map((tool,i)=>`<button id="studio-tab-${tool.id}" role="tab" data-studio-tab="${tool.id}" aria-selected="${i===0}" aria-controls="${tool.id}" tabindex="${i===0?0:-1}"><span>0${i+1}</span>${tool.title}</button>`).join('')}</nav>
<section class="tool-panel" id="prompt" role="tabpanel" aria-labelledby="studio-tab-prompt"><div class="tool-panel-heading"><div><span class="eyebrow">01 / NGHĨ RÕ, HỎI RÕ</span><h2>Một yêu cầu có cấu trúc.</h2></div><p>Công cụ ghép mẫu prompt từ thông tin bạn nhập. Bạn chủ động mang prompt sang công cụ AI mình dùng.</p></div><div class="tool-grid"><form id="prompt-form" class="tool-form"><div class="field full"><label for="prompt-topic">Bạn muốn nói về điều gì?</label><textarea id="prompt-topic" name="topic" required maxlength="500" rows="3" placeholder="Ví dụ: Vì sao RAM và dung lượng ổ cứng khác nhau?"></textarea></div><div class="field"><label for="prompt-type">Loại nội dung</label><select id="prompt-type" name="type"><option value="post">Bài đăng Facebook</option><option value="script">Kịch bản video ngắn</option><option value="explain">Giải thích dễ hiểu</option><option value="verify">Kế hoạch kiểm chứng</option></select></div><div class="field"><label for="prompt-audience">Người đọc mục tiêu</label><input id="prompt-audience" name="audience" maxlength="150" value="Người mới tìm hiểu công nghệ"></div><div class="field"><label for="prompt-length">Độ dài</label><select id="prompt-length" name="length"><option value="short">Ngắn gọn</option><option value="medium">Vừa đủ</option><option value="detailed">Chi tiết</option></select></div><div class="field"><label for="prompt-tone">Giọng điệu</label><select id="prompt-tone" name="tone"><option value="clear">Rõ ràng, dễ hiểu</option><option value="friendly">Gần gũi</option><option value="professional">Chuyên nghiệp</option></select></div><div class="field full"><label for="prompt-context">Ngữ cảnh hoặc nguồn bạn có (tùy chọn)</label><textarea id="prompt-context" name="context" rows="4" maxlength="3000" placeholder="Ghi thông tin công khai bạn muốn đưa vào prompt. Không nhập dữ liệu bí mật."></textarea></div><button class="button button-blue" type="submit">Tạo cấu trúc prompt ↗</button><span class="tool-feedback" id="prompt-status" role="status"></span></form><div class="tool-output"><span class="output-kicker">PROMPT CỦA BẠN</span><label class="sr-only" for="prompt-result">Prompt đã tạo</label><textarea id="prompt-result" readonly placeholder="Prompt của bạn sẽ xuất hiện ở đây…" rows="18"></textarea><div class="output-actions"><button class="button button-outline" data-copy-output="prompt-result" disabled>Sao chép</button><button class="text-button" id="download-prompt" disabled>Tải .txt ↗</button></div><p>Mẫu không tự kiểm chứng nội dung và không gọi mô hình AI. Hãy đọc lại kết quả do AI trả về trước khi sử dụng.</p></div></div></section>
<section class="tool-panel" id="transfer" role="tabpanel" aria-labelledby="studio-tab-transfer" hidden><div class="tool-panel-heading"><div><span class="eyebrow">02 / TỪ CON SỐ ĐẾN TRẢI NGHIỆM</span><h2>Tệp này tải trong bao lâu?</h2></div><p>Ước lượng bằng tốc độ bạn nhập. Đây là phép tính lý thuyết, không phải phép đo tốc độ mạng.</p></div><div class="tool-grid"><form id="transfer-form" class="tool-form"><div class="field full"><label for="transfer-speed">Tốc độ đường truyền (Mbps)</label><input id="transfer-speed" name="speed" type="number" min="0.001" max="1000000" step="any" value="100" required><small>Mbps là megabit mỗi giây. Một byte gồm 8 bit.</small></div><div class="field"><label for="transfer-size">Dung lượng tệp</label><input id="transfer-size" name="size" type="number" min="0.001" step="any" value="1" required></div><div class="field"><label for="transfer-unit">Đơn vị dung lượng</label><select id="transfer-unit" name="unit"><option>GB</option><option>MB</option><option>GiB</option><option>MiB</option></select></div><div class="field full"><label for="transfer-loss">Hệ số giảm giả định: <strong id="transfer-loss-value">10%</strong></label><input id="transfer-loss" name="loss" type="range" min="0" max="50" value="10"><small>Mô phỏng mức tốc độ hữu dụng thấp hơn con số nhập. Đây không phải mức hao hụt cố định của mọi mạng.</small></div><button class="button button-blue" type="submit">Tính thời gian ước lượng ↗</button><span class="tool-feedback" id="transfer-status" role="status"></span></form><div class="transfer-results tool-output"><span class="output-kicker">THỜI GIAN ƯỚC LƯỢNG</span><strong class="transfer-time" id="transfer-time">—</strong><div class="transfer-metrics"><div><span id="transfer-effective">—</span><small>Mbps hữu dụng</small></div><div><span id="transfer-mbs">—</span><small>MB/s thập phân</small></div></div><div class="transfer-formula">Thời gian = số byte × 8 ÷ số bit truyền mỗi giây</div><p>Thực tế còn phụ thuộc máy chủ, độ ổn định, tải mạng và thiết bị. GB dùng hệ thập phân; GiB dùng hệ nhị phân.</p><a class="text-button" href="https://physics.nist.gov/cuu/Units/binary.html" target="_blank" rel="noopener noreferrer">Đọc về đơn vị dữ liệu tại NIST ↗</a></div></div></section>
<section class="tool-panel" id="utm" role="tabpanel" aria-labelledby="studio-tab-utm" hidden><div class="tool-panel-heading"><div><span class="eyebrow">03 / CHIA SẺ CÓ TỔ CHỨC</span><h2>Đặt tên cho nguồn truy cập.</h2></div><p>Tạo liên kết có tham số UTM. Công cụ chỉ tạo URL; không tự theo dõi người dùng hoặc bật hệ thống thống kê.</p></div><div class="tool-grid"><form id="utm-form" class="tool-form"><div class="field full"><label for="utm-url">Địa chỉ đích HTTPS</label><input id="utm-url" name="url" type="url" required placeholder="Dán địa chỉ website bạn muốn chia sẻ"></div><div class="field"><label for="utm-source">Nguồn (source)</label><input id="utm-source" name="source" required maxlength="150" value="facebook"></div><div class="field"><label for="utm-medium">Kênh (medium)</label><input id="utm-medium" name="medium" required maxlength="150" value="social"></div><div class="field full"><label for="utm-campaign">Tên chiến dịch (campaign)</label><input id="utm-campaign" name="campaign" required maxlength="150" placeholder="Ví dụ: cam-nang-cong-nghe"></div><div class="field"><label for="utm-content">Phân biệt nội dung (tùy chọn)</label><input id="utm-content" name="content" maxlength="150" placeholder="bai-dang-01"></div><div class="field"><label for="utm-term">Từ khóa (tùy chọn)</label><input id="utm-term" name="term" maxlength="150"></div><button class="button button-blue" type="submit">Tạo liên kết UTM ↗</button><span class="tool-feedback" id="utm-status" role="status"></span></form><div class="tool-output utm-output"><span class="output-kicker">LIÊN KẾT CỦA BẠN</span><label class="sr-only" for="utm-result">Liên kết UTM</label><textarea id="utm-result" readonly rows="7" placeholder="Liên kết đúng cấu trúc sẽ xuất hiện ở đây…"></textarea><div class="output-actions"><button class="button button-outline" data-copy-output="utm-result" disabled>Sao chép liên kết</button></div><p>Không đặt email, số điện thoại hoặc thông tin nhạy cảm trong tham số. Muốn xem báo cáo, trang đích phải có hệ thống đo lường phù hợp.</p><a class="text-button" href="https://support.google.com/analytics/answer/10917952?hl=en" target="_blank" rel="noopener noreferrer">Hướng dẫn UTM của Google ↗</a></div></div></section>
<section class="tool-panel" id="publish" role="tabpanel" aria-labelledby="studio-tab-publish" hidden><div class="tool-panel-heading"><div><span class="eyebrow">04 / RÀ SOÁT TRƯỚC KHI CHIA SẺ</span><h2>Một lần kiểm tra, thêm yên tâm.</h2></div><p>Danh sách tự rà soát giúp bạn giữ nhịp làm việc. Hoàn thành danh sách không thay thế việc kiểm chứng hoặc đánh giá chuyên môn.</p></div><div class="publish-progress"><strong id="publish-count">0 / ${W.checks.length}</strong><div class="mini-progress"><span id="publish-bar" style="width:0%"></span></div><span id="publish-status" role="status">Bạn chưa đánh dấu mục nào.</span></div><div class="publish-checklist">${[...new Set(W.checks.map(c=>c.group))].map(group=>`<fieldset><legend>${group}</legend>${W.checks.filter(c=>c.group===group).map(c=>`<label><input type="checkbox" data-publish-check="${c.id}"><span>${c.text}</span></label>`).join('')}</fieldset>`).join('')}</div><div class="publish-actions"><button class="button button-outline" id="export-checklist">Tải danh sách của tôi ↗</button><button class="text-button" id="reset-checklist">Bỏ mọi dấu chọn</button></div></section>
${(typeof module==='object'&&module.exports?require('./creator-markup.js'):root.THCreatorMarkup).studioExtras()}<div class="studio-footer-note"><span>TH</span><p>Các công cụ không gửi dữ liệu nhập tới dịch vụ xử lý bên ngoài. Prompt, dấu chọn rà soát và kịch bản bạn chọn lưu được giữ trên trình duyệt này. Quản lý tại trang Dữ liệu & hiển thị.</p></div>`;}
const api={body};if(typeof module==='object'&&module.exports)module.exports=api;else root.THStudioMarkup=api;
})(typeof window!=='undefined'?window:globalThis);
